mapper.select:
SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_chat_bot_cfg a
WHERE status_cd = '00A'
  AND space_id = #{dto.spaceId}
  AND bot_id = #{dto.botId}
  AND bot_tenant_id = #{dto.botTenantId}
  AND user_id = #{dto.userId}
  AND action_type = #{dto.actionType}

